   377→        public SyncResponseHandlingResult HandleResponse(BlocksRequest response, PeerInfo? peer)
   378→        {
   379→            using var _ = response;
   380→            BlockBody[]? bodies = response.OwnedBodies?.Bodies;
   381→            response.OwnedBodies?.Disown();
   382→
   383→            SyncResponseHandlingResult result = SyncResponseHandlingResult.OK;
   384→            using ArrayPoolList<Block> blocks = new ArrayPoolList<Block>(response.BodiesRequests?.Count ?? 0);
   385→            int bodiesCount = 0;
   386→            int receiptsCount = 0;
   387→
   388→            for (int i = 0; i < response.BodiesRequests.Count; i++)
   389→            {
   390→                BlockHeader header = response.BodiesRequests[i];
   391→                if (!_downloadRequests.TryGetValue(header.Hash, out BlockEntry entry))
   392→                {
   393→                    continue;
   394→                }
   395→
   396→                if ((bodies?.Length ?? 0) <= i)
   397→                {
   398→                    entry.RetryBlockRequest();
   399→                    continue;
   400→                }
   401→
   402→                BlockBody? body = bodies[i];
   403→                if (body is null)
   404→                {
   405→                    entry.RetryBlockRequest();
   406→                    continue;
   407→                }
   408→
   409→                if (!_blockValidator.ValidateBodyAgainstHeader(entry.Header, body, out string errorMessage))
   410→                {
   411→                    if (_logger.IsWarn) _logger.Warn($"Invalid downloaded block from {peer}, {errorMessage}");
   412→
   413→                    if (peer is not null) _syncPeerPool.ReportBreachOfProtocol(peer, DisconnectReason.ForwardSyncFailed, $"invalid block received: {errorMessage}. Block: {entry.Header.ToString(BlockHeader.Format.Short)}");
   414→                    result = SyncResponseHandlingResult.LesserQuality;
   415→                    entry.RetryBlockRequest();
   416→                    continue;
   417→                }
   418→
   419→                Block block = new Block(entry.Header, body);
   420→
   421→                if (_logger.IsTrace) _logger.Trace($"Adding block to requests map {entry.Header.Number}");
   422→                entry.Block = block;
   423→                entry.PeerInfo = peer;
   424→                blocks.Add(block);
   425→                bodiesCount++;
   426→            }
   427→
   428→            if (result == SyncResponseHandlingResult.OK)
   429→            {
   430→                if (bodiesCount > 0)
   431→                {
   432→                    long txCount = 0;
   433→                    foreach (var block in blocks)
   434→                    {
   435→                        txCount += block.Transactions?.Length ?? 0;
   436→                    }
   437→                    _estimateTxPerBlock = (int)Math.Max(txCount / blocks.Count, MinEstimateTxPerBlock);
   438→                }
   439→            }
   440→
   441→            for (int i = 0; i < response.ReceiptsRequests.Count; i++)
   442→            {
   443→                BlockHeader header = response.ReceiptsRequests[i];
   444→                if (!_downloadRequests.TryGetValue(header.Hash, out BlockEntry entry))
   445→                {
   446→                    continue;
   447→                }
   448→
   449→                if ((response.Receipts?.Count ?? 0) <= i)
   450→                {
   451→                    entry.RetryReceiptRequest();
   452→                    continue;
   453→                }
   454→
   455→                TxReceipt[]? receipts = response.Receipts[i];
   456→                if (receipts is null)
   457→                {
   458→                    entry.RetryReceiptRequest();
   459→                    continue;
   460→                }
   461→
   462→                Block block = entry.Block!;
   463→
   464→                if (block is null)
   465→                {
   466→                    // Could happen if the buffer is reduced and then reenlarged.
   467→                    entry.RetryBlockRequest();
   468→                    entry.RetryReceiptRequest();
   469→                    continue;
   470→                }
   471→
   472→                if (_receiptsRecovery.TryRecover(block, receipts, false) == ReceiptsRecoveryResult.Fail)
   473→                {
   474→                    if (_logger.IsDebug) _logger.Debug($"Recovery failure from {peer} for block {header.ToString(BlockHeader.Format.Short)}");
   475→                    if (peer is not null) _syncPeerPool.ReportBreachOfProtocol(peer, DisconnectReason.ForwardSyncFailed, "receipt recovery failed");
   476→                    result = SyncResponseHandlingResult.LesserQuality;
   477→                    entry.RetryReceiptRequest();
   478→                    continue;
   479→                }
   480→                if (!ValidateReceiptsRoot(block, receipts))
   481→                {
   482→                    if (_logger.IsDebug) _logger.Debug($"Invalid receipt root from {peer} for block {header.ToString(BlockHeader.Format.Short)}");
   483→
   484→                    if (peer is not null) _syncPeerPool.ReportBreachOfProtocol(peer, DisconnectReason.ForwardSyncFailed, "invalid receipt root");
   485→                    result = SyncResponseHandlingResult.LesserQuality;
   486→                    entry.RetryReceiptRequest();
   487→                    continue;
   488→                }
   489→
   490→                if (_logger.IsTrace) _logger.Trace($"Adding receipts to requests map {entry.Header.Number}");
   491→                entry.Receipts = receipts;
   492→                entry.PeerInfo = peer;
   493→                receiptsCount++;
   494→            }
   495→
   496→            if (result == SyncResponseHandlingResult.OK)
   497→            {
   498→                // Request and body does not have the same size so this hueristic is wrong.
   499→                if (bodiesCount + receiptsCount == 0)
   500→                {
   501→                    // Trigger sleep
   502→                    result = SyncResponseHandlingResult.LesserQuality;
   503→                }
