   131→        public void AddNewBlock(Block block, ISyncPeer nodeWhoSentTheBlock)
   132→        {
   133→            if (!_gossipPolicy.CanGossipBlocks) return;
   134→            if (block.Difficulty == 0) return; // don't gossip post merge blocks
   135→
   136→            if (block.TotalDifficulty is null)
   137→            {
   138→                throw new InvalidDataException("Cannot add a block with unknown total difficulty");
   139→            }
   140→
   141→            if (block.Hash is null)
   142→            {
   143→                throw new InvalidDataException("Cannot add a block with unknown hash");
   144→            }
   145→
   146→            // Now, there are some complexities here.
   147→            // We can have a scenario when a node sends us a block whose parent we do not know.
   148→            // In such cases we cannot verify the total difficulty of the block
   149→            // but we do want to update the information about what the peer believes its total difficulty is.
   150→            // This is tricky because we may end up preferring the node over others just because it is convinced
   151→            // to have higher total difficulty .
   152→            // Also, note, Parity consistently sends invalid TotalDifficulty values both on Clique and Mainnet.
   153→            // So even validating the total difficulty and disconnecting misbehaving nodes leads to problems
   154→            // - it creates an impression of Nethermind being unstable with peers.
   155→            // So, in the end, we decide to update the peer info, but soon after nullify the TotalDifficulty information
   156→            // so that the block tree may actually calculate it when the parent is known.
   157→            // (in case the parent is unknown the tree will ignore the block anyway).
   158→            // The other risky scenario (as happened in the past) is when we nor validate the TotalDifficulty
   159→            // neither nullify it and then BlockTree may end up saving a header or block with incorrect value set.
   160→            // This may lead to corrupted block tree history.
   161→            UpdatePeerInfoBasedOnBlockData(block, nodeWhoSentTheBlock);
   162→
   163→            // Now it is important that all the following checks happen after the peer information was updated
   164→            // even if the block is not something that we want to include in the block tree
   165→            // it delivers information about the peer's chain.
   166→
   167→            bool isBlockBeforeTheSyncPivot = block.Number < _pivotNumber;
   168→            bool isBlockOlderThanMaxReorgAllows = block.Number < (_blockTree.Head?.Number ?? 0) - Sync.MaxReorgLength;
   169→
   170→            // We skip blocks that are old
   171→            if (isBlockBeforeTheSyncPivot || isBlockOlderThanMaxReorgAllows)
   172→            {
   173→                return;
   174→            }
   175→
   176→            // We skip already imported blocks
   177→            if (_blockTree.IsKnownBlock(block.Number, block.Hash))
   178→            {
   179→                return;
   180→            }
   181→
   182→            if (_recentlySuggested.Set(block.Hash, nodeWhoSentTheBlock))
   183→            {
   184→                if (_specProvider.TerminalTotalDifficulty is not null && block.TotalDifficulty >= _specProvider.TerminalTotalDifficulty)
   185→                {
   186→                    if (_logger.IsInfo) _logger.Info($"Peer {nodeWhoSentTheBlock} sent block {block} with total difficulty {block.TotalDifficulty} higher than TTD {_specProvider.TerminalTotalDifficulty}");
   187→                }
   188→
   189→                Block? parent = _blockTree.FindBlock(block.ParentHash);
   190→                if (parent is not null)
   191→                {
   192→                    // we null total difficulty for a block in a block tree as we don't trust the message
   193→                    UInt256? totalDifficulty = block.TotalDifficulty;
   194→
   195→                    // Recalculate total difficulty as we don't trust total difficulty from gossip
   196→                    block.Header.TotalDifficulty = parent.TotalDifficulty + block.Header.Difficulty;
   197→                    if (!_blockValidator.ValidateSuggestedBlock(block, parent.Header, out _))
   198→                    {
   199→                        ThrowOnInvalidBlock(block, nodeWhoSentTheBlock);
   200→                    }
   201→
   202→                    if (!ValidateSeal(block, nodeWhoSentTheBlock))
   203→                    {
   204→                        ThrowOnInvalidBlock(block, nodeWhoSentTheBlock);
   205→                    }
   206→
   207→                    // we want to broadcast original block, lets check if TD changed
   208→                    Block blockToBroadCast = totalDifficulty == block.TotalDifficulty
   209→                        ? block
   210→                        : new(block.Header.Clone(), block.Body) { Header = { TotalDifficulty = totalDifficulty } };
   211→
   212→                    BroadcastBlock(blockToBroadCast, false, nodeWhoSentTheBlock);
   213→
   214→                    SyncMode syncMode = _syncModeSelector.Current;
   215→                    bool notInFastSyncNorStateSyncNorSnap = (syncMode & (SyncMode.FastSync | SyncMode.StateNodes | SyncMode.SnapSync)) == SyncMode.None;
   216→                    bool inFullSyncOrWaitingForBlocks = (syncMode & (SyncMode.Full | SyncMode.WaitingForBlock)) != SyncMode.None;
   217→                    if (notInFastSyncNorStateSyncNorSnap || inFullSyncOrWaitingForBlocks)
   218→                    {
   219→                        LogBlockAuthorNicely(block, nodeWhoSentTheBlock);
   220→                        SyncBlock(block, nodeWhoSentTheBlock);
   221→                    }
   222→                }
   223→                else
   224→                {
   225→                    LogBlockAuthorNicely(block, nodeWhoSentTheBlock);
   226→                    if (_logger.IsDebug) _logger.Debug($"Peer {nodeWhoSentTheBlock} sent block with unknown parent {block}, best suggested {_blockTree.BestSuggestedHeader}.");
   227→                }
   228→            }
   229→        }
   230→
   231→        private void ThrowOnInvalidBlock(Block block, ISyncPeer nodeWhoSentTheBlock)
   232→        {
   233→            string message = $"Peer {nodeWhoSentTheBlock.Node:c} sent an invalid block.";
   234→            if (_logger.IsDebug) _logger.Debug(message);
   235→            _recentlySuggested.Delete(block.Hash!);
   236→            throw new EthSyncException(message);
   237→        }
   238→
   239→        private bool ValidateSeal(Block block, ISyncPeer syncPeer)
   240→        {
   241→            if (_logger.IsTrace) _logger.Trace($"Validating seal of {block.ToString(Block.Format.Short)}) from {syncPeer:c}");
   242→
   243→            // We hint validation range mostly to help ethash to cache epochs.
   244→            // It is important that we only do that here, after we ensured that the block is
   245→            // in the range of [Head - MaxReorganizationLength, Head].
   246→            // Otherwise we could hint incorrect ranges and cause expensive cache recalculations.
   247→            _sealValidator.HintValidationRange(_sealValidatorUserGuid, block.Number - 128, block.Number + 1024);
   248→            return _sealValidator.ValidateSeal(block.Header, true);
   249→        }
